"""Reviewed comparisons; explicit evidence and falsification, never label-only joins."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
OUT=ROOT/'analysis';OUT.mkdir(exist_ok=True)
def evidence(ref,lines):
 d=json.loads((ROOT/'mission-3/sources'/ref/'source.json').read_text())['documents'][0];ss=(ROOT/d['path']).read_text().splitlines()
 return [{'source_id':'M3-SRC-'+ref+'-'+d['id'],'document_id':d['id'],'locator':d['path']+':L'+str(n),'original':ss[n-1],'extraction_method':'Reviewed complete source paragraph/table line','transformation':'Source retained verbatim; comparison inference separately labeled','status':'PUBLISHED'} for n in lines]
rows=[]
def add(key,title,level,family,sources,features,difference,test,outcome,classification,strength='moderate',limitation='No inference about actual respondent performance or agency intent.'):
 rows.append(dict(id='CMP-'+key,title=title,level=level,family=family,refs=list(sources),epistemic_status='INFERRED',similarity={'strength':strength,'observable_matches':features,'unknowns':'Unpublished measurement samples and internal review procedures are unknown unless specifically cited.','rationale':'Comparability applies only to the named component, actor and source-defined unit; independent collections and serial versions are distinguished.'},difference_observed=difference,candidate_explanation_tested=test,evidence_assessed=outcome,classification=classification,limitations=limitation,provenance=[p for ref,ls in sources.items() for p in evidence(ref,ls)]))
add('01','Industry-requested carrier and cargo amendments','cross_ICR','task_duration',{'202406-1652-001':[122],'202411-1652-003':[83],'202402-1652-002':[104]},'Regulated operator prepares a request to change an existing security program; recurring per-request respondent task; managerial/security role.','Each uses 1 hour per request.','Separate industry requests from TSA-issued directives, initial plans and Federal review.','All three paragraphs explicitly isolate industry/carrier requests; cargo practice approvals may be narrower. Equality is supported for the published scalar.','CONSISTENT')
add('02','Surface training amendments across modes and transfer','cross_ICR_and_lineage','task_duration',{'202304-1652-002':[118,129,140],'202504-1652-004':[109]},'Security coordinator amends an existing STP; annual operator population.','8 hours and 10% annual amendment share in all three modes and the receiving collection.','Test whether transfer creates independent corroboration or a new requirement.','2025 explicitly consolidates 1652-0066 into the receiving collection. This is continuity of assumptions, not four independent estimates.','CONSISTENT','strong')
add('03','Training record entry across surface modes','within_ICR','recordkeeping',{'202304-1652-002':[164,175,186]},'Administrative assistant enters a new/updated employee training record; per-record recurring task.','1 minute per record across freight rail, PTPR and OTRB.','Check whether the number represents training attendance rather than record entry.','Source paragraphs isolate recordkeeping; training itself is outside this task.','CONSISTENT','strong')
add('04','Airport and carrier-requested amendments','cross_ICR','task_duration',{'202412-1652-001':[7,144],'202406-1652-001':[122]},'Operator requests a change to an existing TSA security program; respondent preparation per amendment.','Airport preparation 25 hours versus carrier request documentation 1 hour.','Test implementation scope, complexity and whether the same deliverable is timed.','Airport obligation includes development, submission and implementation; timed paragraph does not decompose preparation. Carrier paragraph isolates request documentation. Public text does not establish equal complexity or full task boundaries.','UNRESOLVED',limitation='The 25:1 published ratio is not an estimated inefficiency or a retained inconsistency.')
add('05','Coordinator contact updates across surface and pipeline collections','cross_ICR','task_duration',{'202606-1652-001':[183,185],'202504-1652-005':[107,169]},'Owner/operator submits changed cybersecurity coordinator contact information; recurring update.','Surface 5 minutes for a new coordinator or alternate; pipeline 30 minutes for coordinator and/or alternate update.','Test person versus operator bundle and whether initial designation is included.','Both cover updates, but pipeline cardinality and task detail are not decomposed; one operator event may encompass more work than one person contact.','UNRESOLVED',limitation='Do not call the 6:1 ratio inconsistent; event cardinality and scope remain unresolved.')
add('06','Pipeline compensation loading with aligned source vintage','cross_ICR','benefit_loading',{'202601-1652-004':[140],'202512-1652-001':[259]},'Respondent transportation/material-moving compensation-to-wage loading; December 2024 source period.','1.467370066 versus 1.467370.','Check precision, source period and employee universe.','Difference is displayed precision at six decimals; source period and occupational universe align.','CONSISTENT','strong')
add('07','Loading variation by employee universe and source vintage','cross_ICR','benefit_loading',{'202412-1652-001':[294],'202406-1652-001':[254]},'Ratio of total hourly compensation to wages used to monetize respondent labor.','1.454667 full-time private industry, June 2024; 1.4582 transportation/material-moving source, March 2023.','Test vintage and worker universe before treating unequal ratios as inconsistency.','Different cited populations and periods explain why the ratios differ. This does not establish that each proxy is optimal; domestic paragraph also has a month-label ambiguity.','DIFFERENT_EXPLAINED',limitation='Explanation of numeric variation is not an endorsement of proxy selection; March/June wording ambiguity retained.')
add('08','Medical applicant wage and waiting-time conventions','cross_ICR','occupational_assignment',{'202605-1652-001':[55,73],'202606-1652-003':[66,68]},'Public applicants completing medical clearance; opportunity-cost valuation and waiting-room time.','Both use $32.66 mean wage, 1.4582 loading and 11-minute waiting assumption.','Separate public applicant time from provider time and incumbent Federal employee duties.','Published applicant components align; FAMS provider compensation and incumbent travel have different actor boundaries.','CONSISTENT','strong')
add('09','Medical applicant travel assumptions','cross_ICR','task_duration',{'202605-1652-001':[73,136],'202606-1652-003':[66,122,123,124,125]},'Applicant travels to a local medical provider; both model a round trip and monetize public applicant time.','FAMS uses 20 minutes each way; TSO uses 34 each way.','Inspect cited study populations, dates and whether travel statistic is one-way or daily total.','Different studies visibly explain source selection. Primary Altarum brief describes diary-day travel rather than explicitly one-way travel; TSO doubling needs clarification. FAMS source surveys adults aged 50+, not a measured applicant sample.','UNRESOLVED',limitation='Source-selection difference is observable; neither a corrected TSO total nor applicant-specific travel accuracy is established. See external-source-review.json.')
add('10','Online credential renewal times','cross_ICR','renewal',{'202504-1652-008':[58,140],'202606-1652-002':[217],'202605-1652-002':[238,251]},'Existing credential holders renew online; per-application active submission.','TWIC and HME use 10 minutes; PreCheck uses 1.8 minutes and a separate conditional biometrics activity.','Test measured versus conservative estimate, biometric scope and identical form content.','TWIC reports pilot completion faster than its retained conservative estimate. PreCheck separately models conditional biometric submission; common credential labels do not prove equal form content.','UNRESOLVED',limitation='Do not treat conditional biometrics as duplicate renewals or equate published time to measured time for all programs.')
add('11','Federal and contractor comment processing','within_ICR','federal_review_time',{'202504-1652-006':[119]},'Electronic customer comments in the same workflow.','0.5 minute Federal threat triage versus 5 minutes contractor read/respond.','Test actor and workflow stage.','Source separates security triage from reading and selecting a response template. Different task boundaries explain the values.','DIFFERENT_EXPLAINED','strong')
add('12','FFDO interview burden removed','lineage','item15_baseline',{'202411-1652-006':[13,95]},'Same FFDO applicant certification process after workflow revision.','10-minute verbal interview removed.','Test whether reduction is unexplained estimation drift.','Source explicitly moves certification questions online and removes duplicative interview questions. This explains the task deletion, not a fully reconciled numerical Item 15 bridge.','DIFFERENT_EXPLAINED','strong')
add('13','LEO checkpoint login duration change','lineage','task_duration',{'202509-1652-001':[64,86],'202206-1652-001':[53]},'Same LEO checkpoint login form; respondent submission.','Prior 1 minute becomes 4 minutes.','Test whether collection change or renewed timing basis is documented.','Recent Item 15 cites user-experience feedback as basis. Published explanation supports changed estimate; underlying timing sample is not public.','DIFFERENT_EXPLAINED','strong')
add('14','Federal amendment-review bundles','cross_ICR','federal_review_time',{'202402-1652-002':[141],'202411-1652-003':[123,125]},'TSA review of industry-requested security-program amendments; Federal active labor.','IAC 120 hours versus FAC 4 hours field review plus 6.75 hours headquarters review.','Test elapsed versus active time, multiple reviewers, amendment type and task decomposition.','IAC converts fifteen days into 120 hours without decomposition and pools TSA-issued and industry-requested amendments. FAC separately describes research/drafting and headquarters review. Identical case complexity and staffing are not established.','UNRESOLVED',limitation='No inference that a fifteen-day period is necessarily elapsed time or that the pooled IAC mean equals the industry-only mean.')
add('15','Medical examination payer change','lineage','purchased_services',{'202606-1652-003':[103]},'Medical screening requirement; resource cost and payer boundaries.','Contractor Federal cost removed and candidate $150 per exam added for 18,000 exams.','Test whether cost reduction is an efficiency gain or a transfer of payer.','Statement explicitly assigns local examination cost to candidates. Payer change explains category movement; no claim of net savings.','DIFFERENT_EXPLAINED','strong')
for r in rows:
 r['adversarial_challenge']={'hypothesis_to_falsify':r['classification'],'alternative':r['candidate_explanation_tested'],'result':r['evidence_assessed'],'retained_classification':r['classification'],'method':'Read cited source paragraphs, separate actor/task/unit/period; test scope and lineage alternatives before classification.'}
if __name__ == '__main__':
 (OUT/'comparisons.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
 print('comparisons',len(rows))
